@riverpod
class CardNotifier extends _$CardNotifier {
  late final MatchRepository _matchRepository;
  late final MailboxRepository _mailboxRepository;
  bool isMatch = false;
  bool? isLike;
  bool isLoadingMailbox = false;
  bool isMailboxSent = false;

  @override
  CardState build(String targetUserId) {
    _matchRepository = ref.watch(matchRepositoryProvider);
    _mailboxRepository = ref.watch(mailboxRepositoryProvider);
    return CardState(
      isMatch: isMatch,
      isLoadingMailbox: isLoadingMailbox,
      isMailboxSent: isMailboxSent,
    );
  }

  void dislike(String content) async {
    try {
      final result = await _matchRepository.dislike(targetUserId: targetUserId);
      isMatch = result?.isMatched ?? false;
      isLike = false;
      state = CardState(
        isMatch: isMatch,
        isLike: isLike,
        isLoadingMailbox: isLoadingMailbox,
        isMailboxSent: isMailboxSent,
      );
    } on ErrorData catch (e) {
      isLike = null;
      isMatch = false;
      state = CardState(
        isMatch: isMatch,
        isLike: isLike,
        isLoadingMailbox: isLoadingMailbox,
        isMailboxSent: isMailboxSent,
      );
    }
  }
}

class RefreshTokenInterceptor extends Interceptor {
  RefreshTokenInterceptor(this.baseHttpClient, this.parentContainer);

  final BaseHttpClient baseHttpClient;
  final ProviderContainer parentContainer;

  @override
  Future<void> onResponse(
    Response<dynamic> response,
    ResponseInterceptorHandler handler,
  ) async {
    try {
      final header = response.requestOptions.headers;
      if ((response.statusCode ?? 0) >= 400 && (response.statusCode ?? 0) < 500) {
        final baseResponse = BaseResponse.fromJson(json: response.data);
        if (baseResponse.status == ErrorUtil.codeRefreshTokenExpiredError ||
            baseResponse.status == ErrorUtil.codeTokenInvalidError ||
            baseResponse.status == ErrorUtil.codeUserNotFoundError) {
          Util.logout(context: appRouter.navigatorKey.currentContext);
          return;
        }
        if ((response.statusCode ?? 0) == 401) {
          final SignUpData? value = await getRefreshToken();
          if (value == null) {
            handler.resolve(response);
          } else {
            header["Authorization"] =
                "Bearer ${await CacheUtil.getString(Strings.keyAccessToken)}";
            dynamic newData = response.requestOptions.data;
            if (newData is FormData) {
              newData = await _remakeFormData(newData, response.requestOptions.extra);
            }
            final Response<dynamic> value = await baseHttpClient.client
                .fetch<dynamic>(response.requestOptions
                    .copyWith(headers: header, data: newData));
            handler.resolve(value);
            return;
          }
        }
      }
      super.onResponse(response, handler);
    } catch (e) {
      return;
    }
  }

  Future<FormData> _remakeFormData(
      FormData oldData, Map<String, dynamic> requestExtra) async {
    final Map<String, dynamic> newFormData = Map.fromEntries(oldData.fields);
    for (var file in oldData.files) {
      newFormData.putIfAbsent(file.key, () => file.value.clone());
    }
    return FormData.fromMap(newFormData);
  }
}

import 'package:auto_route/auto_route.dart';
import 'package:lovelet_lookin/common/resource/strings.dart';
import 'package:lovelet_lookin/common/util/cache_util.dart';
import 'package:lovelet_lookin/router/app_route.dart';

class LoginRouteGuard extends AutoRouteGuard {
  @override
  void onNavigation(NavigationResolver resolver, StackRouter router) async {
    CacheUtil.getBoolean(Strings.keyIsLogin).then(
      (isLogin) {
        if (isLogin) {
          CacheUtil.getBoolean(Strings.keyIsNewUser).then((isNewUser) {
            if (isNewUser) {
              router.push(const RouteNewAccount());
            } else {
              CacheUtil.getBoolean(Strings.keyIsVerified).then(
                (isVerified) {
                  if (isVerified) {
                    router.push(RouteDashboard());
                  } else {
                    router.push(RouteEditProfile(isInitialPage: true));
                  }
                },
              );
            }
          });
        } else {
          resolver.next(true);
        }
      },
    );
  }
}

class BaseResponse<T> {
  final int? status;
  final int? code;
  final String? message;
  final bool? error;
  final T? data;

  BaseResponse({
    this.status,
    this.code,
    this.message,
    this.error,
    this.data,
  });

  factory BaseResponse.fromJson({
    required Map<String, dynamic> json,
    T Function(Map<String, dynamic>)? dataFromJson,
  }) {
    return BaseResponse<T>(
      status: json['status'] as int?,
      code: json['code'] as int?,
      message: json['message'] as String?,
      error: json['error'] as bool?,
      data: json['data'] != null && dataFromJson != null
          ? dataFromJson(json['data'] as Map<String, dynamic>)
          : null,
    );
  }
}

