@override
Future<SendOtpData?> sendOtp({required OtpRequest req}) async {
  try {
    final response = await service.sendOtp(request: req);
    final baseResponse = BaseResponse<SendOtpData>.fromJson(
        json: response.data, dataFromJson: SendOtpData.fromJson);
    if ((baseResponse.error ?? false)) {
      throw ErrorData(code: baseResponse.status, message: baseResponse.message);
    } else {
      return baseResponse.data;
    }
  } on DioException {
    throw ErrorData(code: 500, message: "System error :: network connection");
  }
}

import 'dart:typed_data';
import 'package:flutter_keychain/flutter_keychain.dart';

class CacheUtil {
  CacheUtil._();

  static Future<void> putString(String key, String value) async {
    await FlutterKeychain.put(key: key, value: value);
  }

  static Future<void> putBoolean(String key, bool value) async {
    await FlutterKeychain.put(key: key, value: value.toString());
  }

  static Future<String> getString(String key) async {
    final value = await FlutterKeychain.get(key: key);
    return value ?? '';
  }

  static Future<bool> getBoolean(String key) async {
    final value = await FlutterKeychain.get(key: key);
    return value == 'true';
  }

  static Future<Uint8List?> getUint8List(String key) async {
    final value = await FlutterKeychain.get(key: key);
    if (value == null) return null;
    List<String> stringList =
        value.replaceAll('[', '').replaceAll(']', '').split(', ');
    List<int> intList = stringList.map(int.parse).toList();
    return Uint8List.fromList(intList);
  }

  static Future<void> remove(String key) async {
    await FlutterKeychain.remove(key: key);
  }

  static Future<void> clear() async {
    FlutterKeychain.clear();
  }
}

